    #     this_session <- sessions$value[[i]]
    #     tibble::tibble(id = this_session$id,
    #                    top = this_session$top,
    #                    name = this_session$name)
    #   }
    #   
    #   these_sessions <- tibble::enframe(volume_json$containers)
    #   n_sessions <- dim(these_sessions)[1]
    #   purrr::map(1:n_sessions, extract_single_session, these_sessions) %>%
    #     purrr::list_rbind()
    # }
    # #--------------------------------------------------------------------------
    
    # rq <- rq %>%
    #   httr2::req_url(url = sprintf(GET_VOLUME_SESSIONS, vol_id, MAX_SESSIONS, PAGE_NUM))
    # 
    # if (vb)
    #   message("Retrieving session data for 'vol_id'= ",
    #           vol_id)
    # resp <- tryCatch(
    #   httr2::req_perform(rq),
    #   httr2_error = function(cnd)
    #     NULL
    # )
    # if (is.null(resp)) {
    #   message("Request URL: ", )
    #   message("Cannot access requested resource on Databrary. Exiting.")
    #   return(resp)
    # } else {
    #   these_sessions <- httr2::resp_body_json(resp)
