    # volume_json <- NULL
    # volume_json <- get_volume_by_id(vol_id, vb, rq)
    # volume_sessions <- 
    # session_metadata <- list_volume_session_info(these_sessions)
    session_metadata <- list_volume_sessions(vol_id = vol_id,
                                             vb = vb,
                                             rq = rq)
    
    name <- NULL
    # name_matches <- dplyr::filter(session_metadata, 
    #                               session_name == this_session_name)
    name_matches <- dplyr::filter(session_metadata,
                                  stringr::str_detect(session_name, this_session_name))
    
    if (is.null(name_matches)) {
      message("No matches")
      return(NULL)
    }
    if (dim(name_matches)[1] == 0) {
      message("Empty array")
      return(NULL)
    }
    if (dim(name_matches)[1] > 1) {
      message("\nMultiple sessions with name '", this_session_name, "'.")
    }
    name_matches
    #purrr::map(name_matches$session_id, get_session_by_id, vol_id, rq = rq)
