# Helper function
extract_session_info <- function(x) {
  df = data.frame(vol_id = x$volume,
                  session_id = x$id,
                  session_name = x$name,
                  session_date = x$sourceDate,
                  release_lvl = x$releaseLevel,
                  n_files = x$fileCount)
  df
}